        "id": "O-P-0022-census-1910-own-fields",
        "expectedVersion": 1,
        "action": "revise",
        "value_literal": "u/l-lik råmarkering i nattvardskolumnen; egen yrkes-/stam-/lytescell samt sista trosbekännelse/nationalitet/frånvarokolumn utan saktext",
        "value_json": {
          "communionMarked": true,
          "communionRaw": "u/l-lik markering; bokstav oavkodad",
          "empty": [
            "egen yrkes-/stam-/lytescell",
